const account = $('Get Account').first().json;
const positions = $('Get Positions').all().map(i => i.json);
const watchlist = ($env.WATCHLIST || 'AAPL,MSFT,NVDA,TSLA,AMZN,GOOGL,META,SPY,QQQ').split(',').map(s => s.trim());
const heldSymbols = positions.map(p => p.symbol);
const available = watchlist.filter(s => !heldSymbols.includes(s));
const portfolioValue = parseFloat(account.portfolio_value) || 100000;
const cash = parseFloat(account.cash) || 0;

if (positions.length >= 5) {
  return [{ json: { skip: true, reason: 'Max 5 positions reached', symbols: [] } }];
}

return [{
  json: {
    skip: false,
    account: { portfolio_value: portfolioValue, cash, buying_power: parseFloat(account.buying_power) || 0 },
    positions,
    symbols: available.slice(0, 5 - positions.length)
  }
}];

const barsData = $json;
const symbol = $('Split Symbols').item.json.symbols || $('Split Symbols').item.json;
const bars = barsData.bars?.[symbol] || barsData.bars || [];

if (!bars || bars.length < 20) {
  return [{ json: { symbol, indicators: null, skip: true, reason: 'Insufficient data' } }];
}

const closes = bars.map(b => parseFloat(b.c || b.close));
const highs  = bars.map(b => parseFloat(b.h || b.high));
const lows   = bars.map(b => parseFloat(b.l || b.low));
const vols   = bars.map(b => parseFloat(b.v || b.volume));

const price  = closes[closes.length - 1];
const pct1d  = closes.length >= 2 ? (price / closes[closes.length - 2] - 1) * 100 : 0;
const pct5d  = closes.length >= 6 ? (price / closes[closes.length - 6] - 1) * 100 : 0;

// MAs
const avg = (arr, n) => arr.slice(-n).reduce((a,b) => a+b, 0) / n;
const ma20 = avg(closes, 20);
const ma50 = closes.length >= 50 ? avg(closes, 50) : null;

// Volume
const volToday = vols[vols.length - 1];
const volAvg20 = avg(vols, 20);
const volRatio = volAvg20 > 0 ? volToday / volAvg20 : 1;

// RSI
const calcRSI = (data, period=14) => {
  const deltas = data.slice(1).map((v,i) => v - data[i]);
  let gains = deltas.slice(0, period).filter(d => d > 0).reduce((a,b) => a+b, 0) / period;
  let losses = deltas.slice(0, period).filter(d => d < 0).map(d => -d).reduce((a,b) => a+b, 0) / period;
  for (let i = period; i < deltas.length; i++) {
    const d = deltas[i];
    gains = (gains * (period-1) + Math.max(d, 0)) / period;
    losses = (losses * (period-1) + Math.max(-d, 0)) / period;
  }
  return losses === 0 ? 100 : 100 - (100 / (1 + gains/losses));
};

// MACD
const ema = (data, period) => {
  const k = 2 / (period + 1);
  let e = data[0];
  for (let i = 1; i < data.length; i++) e = data[i] * k + e * (1 - k);
  return e;
};
const macdLine  = ema(closes, 12) - ema(closes, 26);
const macdSignal = ema(closes.slice(-9), 9);
const macdHist  = macdLine - macdSignal;

// BB
const bb_mean = avg(closes, 20);
const bb_std  = Math.sqrt(closes.slice(-20).reduce((s,v) => s + Math.pow(v - bb_mean, 2), 0) / 20);
const bb_upper = bb_mean + 2 * bb_std;
const bb_lower = bb_mean - 2 * bb_std;
const bb_pct   = bb_std > 0 ? (price - bb_lower) / (bb_upper - bb_lower) : 0.5;

const rsi = calcRSI(closes);

const indicators = {
  price: Math.round(price * 100) / 100,
  pct_1d: Math.round(pct1d * 100) / 100,
  pct_5d: Math.round(pct5d * 100) / 100,
  ma20: Math.round(ma20 * 100) / 100,
  ma50: ma50 ? Math.round(ma50 * 100) / 100 : null,
  above_ma20: price > ma20,
  above_ma50: ma50 ? price > ma50 : null,
  vol_ratio: Math.round(volRatio * 100) / 100,
  rsi: Math.round(rsi * 10) / 10,
  macd: Math.round(macdLine * 1000) / 1000,
  macd_signal: Math.round(macdSignal * 1000) / 1000,
  macd_hist: Math.round(macdHist * 1000) / 1000,
  bb_pct: Math.round(bb_pct * 100) / 100,
  bb_upper: Math.round(bb_upper * 100) / 100,
  bb_lower: Math.round(bb_lower * 100) / 100
};

return [{ json: { symbol, indicators, skip: false } }];

const { symbol, indicators, skip } = $json;
if (skip || !indicators) return [{ json: { skip: true } }];

const account = $('Check Market & Build Watchlist').first().json.account;
const positions = $('Check Market & Build Watchlist').first().json.positions;
const schema = 'Respond ONLY with valid JSON (no markdown): {"vote":"BUY"|"SELL"|"HOLD","confidence":0-100,"reason":"one sentence max 20 words"}';

const ind = `Price: $${indicators.price}
1d: ${indicators.pct_1d}%  5d: ${indicators.pct_5d}%
RSI(14): ${indicators.rsi}
MA20: $${indicators.ma20} (${indicators.above_ma20 ? 'ABOVE' : 'BELOW'})
MA50: ${indicators.ma50 ? '$'+indicators.ma50+' ('+(indicators.above_ma50?'ABOVE':'BELOW')+')' : 'N/A'}
Volume ratio: ${indicators.vol_ratio}x
MACD hist: ${indicators.macd_hist}
BB%: ${indicators.bb_pct} (0=lower band, 1=upper band)`;

const agents = [
  {
    agentName: "TrendAgent",
    systemPrompt: "You are a disciplined trend-following analyst.",
    userPrompt: `Analyze ${symbol}.

INDICATORS:
${ind}

BUY if price above MA20+MA50 and MA20>MA50 (uptrend). SELL if below both (downtrend). HOLD if mixed.

${schema}`
  },
  {
    agentName: "TechnicalAgent",
    systemPrompt: "You are a technical analysis expert focusing on RSI, MACD, Bollinger Bands.",
    userPrompt: `Analyze ${symbol}.

INDICATORS:
${ind}

BUY signals: RSI<35, MACD hist turning positive, BB%<0.2. SELL signals: RSI>65, MACD hist negative, BB%>0.8. Need 2 of 3 to agree.

${schema}`
  },
  {
    agentName: "MomentumAgent",
    systemPrompt: "You are a momentum and volume analyst.",
    userPrompt: `Analyze ${symbol}.

INDICATORS:
${ind}

BUY if price up today AND volume ratio>=1.5. SELL if price down AND volume ratio>=1.5. HOLD if volume weak (<1.0).

${schema}`
  },
  {
    agentName: "SentimentAgent",
    systemPrompt: "You are a financial news sentiment analyst. You have access to current news.",
    userPrompt: `Search for latest news on ${symbol}. Look for earnings, upgrades/downgrades, product news, lawsuits.

Current price: $${indicators.price}

BUY: positive catalyst. SELL: negative catalyst. HOLD: no significant news.

${schema}`
  },
  {
    agentName: "MacroAgent",
    systemPrompt: "You are a macro market strategist. You have access to current market data.",
    userPrompt: `Search for: current VIX level, SPY/QQQ trend today, sector performance for ${symbol}.

BUY: risk-on, VIX<20, sector strong. SELL/HOLD: VIX>25, sector weak, major risk event imminent.

${schema}`
  },
  {
    agentName: "RiskAgent",
    systemPrompt: "You are a strict risk manager with VETO POWER. Reject any trade violating hard rules.",
    userPrompt: `PORTFOLIO STATE:
- Value: $${account.portfolio_value}
- Cash: $${account.cash}
- Open positions: ${positions.length}/5

PROPOSED TRADE: ${symbol} @ $${indicators.price}
Estimated cost: $${Math.min(1000, Math.floor(account.portfolio_value * 0.02 / (indicators.price * 0.03)) * indicators.price)}

HARD RULES (any violation = HOLD/SELL):
1. Max 5 open positions (currently ${positions.length})
2. Max $1000 per trade
3. Cash must cover cost
4. Stock price must be >= $5
5. Daily loss limit not breached

BUY only if ALL pass. Confidence 90+ if clearly safe.

${schema}`
  }
];

return agents.map(a => ({ json: { ...a, symbol, indicators } }));

// Map responses back to agent names (same order as prompts)
const agentNames = ['TrendAgent','TechnicalAgent','MomentumAgent','SentimentAgent','MacroAgent','RiskAgent'];
return $input.all().map((item, i) => ({
  json: {
    ...item.json,
    agentName: agentNames[i] || 'Agent' + i
  }
}));

const items = $input.all();

// Parse each agent's vote
const votes = items.map(item => {
  const agentName = item.json.agentName;
  const rawContent = item.json.content?.[0]?.text || item.json.content || '{}';
  const text = typeof rawContent === 'string' ? rawContent : JSON.stringify(rawContent);
  try {
    const clean = text.replace(/```json|```/g, '').trim();
    const data = JSON.parse(clean);
    return {
      agent: agentName,
      vote: (data.vote || 'HOLD').toUpperCase(),
      confidence: Math.min(100, Math.max(0, parseInt(data.confidence) || 50)),
      reason: (data.reason || '').substring(0, 100)
    };
  } catch(e) {
    return { agent: agentName, vote: 'HOLD', confidence: 50, reason: 'Parse error: ' + text.substring(0, 50) };
  }
});

// Consensus rules
const riskVote    = votes.find(v => v.agent === 'RiskAgent');
const riskApproves = riskVote?.vote === 'BUY';
const buyVotes    = votes.filter(v => v.vote === 'BUY');
const sellVotes   = votes.filter(v => v.vote === 'SELL');
const leading     = buyVotes.length >= sellVotes.length ? 'BUY' : 'SELL';
const agreeVotes  = votes.filter(v => v.vote === leading);
const avgConf     = agreeVotes.reduce((s, v) => s + v.confidence, 0) / (agreeVotes.length || 1);

const minVotes = parseInt($env.MIN_VOTES_TO_TRADE || '4');
const minConf  = parseInt($env.MIN_AGENT_CONFIDENCE || '65');
const consensus = agreeVotes.length >= minVotes && avgConf >= minConf && riskApproves && leading === 'BUY';

// Sizing
const firstItem   = items[0].json;
const price       = firstItem.indicators?.price || 0;
const symbol      = firstItem.symbol;
const portfolioV  = 100000; // fallback
const maxPos      = parseFloat($env.MAX_POSITION_SIZE_USD || '1000');
const riskPct     = parseFloat($env.MAX_PORTFOLIO_RISK_PCT || '0.02');
const stopPct     = 0.03;
const tpPct       = 0.06;
const riskDollars = portfolioV * riskPct;
const stopDist    = price * stopPct;
const qty         = Math.max(1, Math.min(Math.floor(riskDollars / stopDist), Math.floor(maxPos / price)));
const stopPrice   = Math.round(price * (1 - stopPct) * 100) / 100;
const tpPrice     = Math.round(price * (1 + tpPct) * 100) / 100;

const voteSummary = votes.map(v => `${v.agent}: ${v.vote} (${v.confidence}%) - ${v.reason}`).join('\n');
console.log(`\n=== CONSENSUS: ${symbol} ===\n${voteSummary}\nFINAL: ${consensus ? 'BUY' : 'HOLD'} | ${agreeVotes.length}/6 agree | avg conf ${Math.round(avgConf)}`);

return [{
  json: {
    symbol, price, qty, stopPrice, tpPrice,
    finalAction: consensus ? 'BUY' : 'HOLD',
    consensusReached: consensus,
    votes, avgConfidence: Math.round(avgConf),
    agreeingCount: agreeVotes.length,
    riskApproves,
    reason: consensus
      ? `${agreeVotes.length}/6 agents voted BUY, avg confidence ${Math.round(avgConf)}`
      : `No consensus: ${agreeVotes.length}/6 for ${leading}, avg conf ${Math.round(avgConf)}, riskApproves=${riskApproves}`
  }
}];

const c = $('Consensus Engine').first().json;
const order = $('Place Buy Order').first().json;
console.log(`\n✅ TRADE EXECUTED: BUY ${c.qty}x ${c.symbol} @ ~$${c.price}`);
console.log(`   Stop: $${c.stopPrice} | Target: $${c.tpPrice}`);
console.log(`   Order ID: ${order.id}`);
console.log(`   Votes: ${c.votes.map(v => v.agent+':'+v.vote).join(', ')}`);
return [{ json: { status: 'executed', symbol: c.symbol, qty: c.qty, price: c.price, orderId: order.id, stopPrice: c.stopPrice, tpPrice: c.tpPrice } }];

const account = $('Get Account').first().json;
const positions = $('Get Positions').all().map(i => i.json);
const watchlist = ($env.WATCHLIST || 'AAPL,MSFT,NVDA,TSLA,AMZN').split(',').map(s=>s.trim()).join(', ');

return [{
  json: {
    systemPrompt: "You are a pre-market research analyst. Search for current news and macro conditions before answering.",
    userPrompt: `Prepare a pre-market brief for today's trading session.

ACCOUNT: Portfolio $${parseFloat(account.portfolio_value).toFixed(0)} | Cash $${parseFloat(account.cash).toFixed(0)} | Open positions: ${positions.length}/5
WATCHLIST: ${watchlist}

Tasks:
1. Search for overnight news on the watchlist symbols
2. Check macro: futures direction, VIX, any major economic releases today
3. Rank top 3 symbols most worth watching at open with reasons
4. Flag any symbols to AVOID today (earnings in 24h, news spike, halt risk)

Format as a concise pre-market brief under 300 words.`
  }
}];

const content = $json.content || [];
const text = content.filter(b => b.type === 'text').map(b => b.text).join(' ');
console.log('\n🌅 PRE-MARKET BRIEF\n' + '='.repeat(50));
console.log(text);
return [{ json: { brief: text, timestamp: new Date().toISOString() } }];

const positions = $input.all().map(i => i.json).filter(p => p.symbol);
if (positions.length === 0) return [{ json: { noPositions: true } }];

const schema = 'Respond ONLY with JSON: {"vote":"BUY"|"SELL"|"HOLD","confidence":0-100,"reason":"one sentence"}';
return positions.map(p => ({
  json: {
    symbol: p.symbol,
    side: p.side,
    unrealized_plpc: parseFloat(p.unrealized_plpc) * 100,
    systemPrompt: "You are a midday position reviewer. Search for current news and price action.",
    userPrompt: `Review existing LONG position in ${p.symbol}.
Current P&L: ${(parseFloat(p.unrealized_plpc)*100).toFixed(1)}%
Entry price: $${parseFloat(p.avg_entry_price).toFixed(2)}
Current price: $${parseFloat(p.current_price).toFixed(2)}

Search for any breaking news or significant price action.
Should we HOLD this position through end of day, or SELL now?

${schema}`
  }
}));

const symbol = $input.first().json.symbol || 'UNKNOWN';
const content = $json.content || [];
const text = content.filter(b => b.type === 'text').map(b => b.text).join(' ');
try {
  const clean = text.replace(/```json|```/g, '').trim();
  const data = JSON.parse(clean);
  const shouldSell = data.vote === 'SELL' && data.confidence >= 60;
  console.log(`Midday review ${symbol}: ${data.vote} (conf=${data.confidence}) - ${data.reason}`);
  return [{ json: { symbol, vote: data.vote, confidence: data.confidence, reason: data.reason, shouldClose: shouldSell } }];
} catch(e) {
  return [{ json: { symbol, vote: 'HOLD', confidence: 50, reason: 'Parse error', shouldClose: false } }];
}

const account = $json;
return [{
  json: {
    systemPrompt: "You are a trading performance analyst.",
    userPrompt: `Write a concise end-of-day trading recap.

FINAL ACCOUNT STATE:
- Portfolio value: $${parseFloat(account.portfolio_value).toFixed(2)}
- Cash: $${parseFloat(account.cash).toFixed(2)}
- Buying power: $${parseFloat(account.buying_power).toFixed(2)}

Write a brief EOD summary (under 150 words) covering:
1. Day summary
2. What worked / what to improve
3. Plan for tomorrow

Keep it professional and concise.`
  }
}];

const content = $json.content || [];
const text = content.filter(b => b.type === 'text').map(b => b.text).join(' ');
console.log('\n🌆 EOD RECAP\n' + '='.repeat(50) + '\n' + text);
return [{ json: { recap: text, timestamp: new Date().toISOString() } }];

const account = $('Get Account').first().json;
const orders = $input.all().map(i => i.json);
const portfolioValue = parseFloat(account.portfolio_value).toFixed(2);

const orderSummary = orders.slice(0, 20).map(o =>
  `${o.symbol}: ${o.side} ${o.qty} @ $${parseFloat(o.filled_avg_price||0).toFixed(2)} (${o.status})`
).join('\n');

return [{
  json: {
    systemPrompt: "You are a senior trading strategist conducting a weekly performance review. Search for relevant market context.",
    userPrompt: `Conduct a weekly trading performance review.

ACCOUNT: $${portfolioValue}

RECENT ORDERS (last 20):
${orderSummary || 'No orders this week'}

STRATEGY RULES:
- 6-agent consensus system (4/6 votes + RiskAgent approval + 65% avg confidence)
- 3% stop-loss, 6% take-profit on all trades
- Max $1000 per position, max 5 positions
- Daily loss limit: $500

Search for: overall market performance this week, sector trends, upcoming events next week.

Write a structured weekly review (under 400 words) covering:
1. Week P&L summary
2. What the agent consensus got right/wrong
3. Market conditions assessment
4. Strategy adjustments to consider
5. Top watchlist symbols for next week
6. Key risk events next week to watch`
  }
}];

const content = $json.content || [];
const text = content.filter(b => b.type === 'text').map(b => b.text).join(' ');
console.log('\n📅 WEEKLY REVIEW\n' + '='.repeat(50) + '\n' + text);
return [{ json: { review: text, timestamp: new Date().toISOString() } }];
